/* Canonical pure scorer source. Its browser copy is generated by sync-v2-visual-scorer.mjs. */
export type V2VisualKind = 'money.allocation.v2' | 'math.number-line.whole.v2' | 'math.number-line.fraction.v2' | 'math.fraction-area.v2' | 'math.bar-model.structure.v2' | 'math.bar-model.answer.v2' | 'math.schema-diagram.structure.v2' | 'math.schema-diagram.slots.v2' | 'math.schema-diagram.answer.v2' | 'math.worked-example.v2' | 'math.function-machine.v2' | 'math.cpa-count.v2' | 'reasoning.decide-justify.v2'
  | 'math.place-value.v2' | 'math.ratio-table.v2' | 'visual.percent-grid.v2' | 'visual.growth-comparison.v2' | 'visual.tax-bracket.v2' | 'logic.savings-rule.v2' | 'visual.goal-bullet.v2' | 'money.running-ledger.v2'
  | 'logic.rule-checker.v2' | 'logic.euler.v2' | 'logic.flowchart.v2' | 'money.spend-decision.v2' | 'logic.sort-by-rule.v2' | 'money.needs-wants.v2' | 'logic.scam-spotter.v2' | 'money.scam-check.v2'
  | 'money.coin-tray.v2' | 'money.making-change.v2' | 'story.branch.v2' | 'story.dialogue-choice.v2' | 'story.would-you-rather.v2'
  | 'visual.chart.v2' | 'money.unit-price.v2' | 'logic.rule-builder.v2';
export type V2VisualVerdict = 'invalid' | 'valid' | 'review' | 'met';
/** B.12 (Law 4): the quality of the reason a learner gave, graded apart from the decision. */
export type V2JudgmentQuality = 'sound' | 'partial' | 'unsupported';

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function fields(value: unknown, names: readonly string[]): value is Record<string, unknown> {
  return record(value) && Object.keys(value).length === names.length && names.every((name) => Object.hasOwn(value, name));
}

function whole(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value);
}

/** A missing rubric checks only the semantic response; the browser never receives hidden answers. */
export function scoreV2Visual(kind: V2VisualKind, payload: unknown, response: unknown, rubric?: unknown): V2VisualVerdict {
  switch (kind) {
    case 'money.allocation.v2': {
      if (!fields(payload, ['total', 'step']) || !whole(payload.total) || payload.total <= 0
        || !whole(payload.step) || payload.step <= 0 || payload.total % payload.step !== 0
        || !fields(response, ['save', 'spend', 'share'])) return 'invalid';
      for (const pocket of ['save', 'spend', 'share']) {
        const value = response[pocket];
        if (!whole(value) || value < 0 || value > payload.total || value % payload.step !== 0) return 'invalid';
      }
      if (response.save as number + (response.spend as number) + (response.share as number) !== payload.total) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['minimumSave']) || !whole(rubric.minimumSave)
        || rubric.minimumSave < 0 || rubric.minimumSave > payload.total || rubric.minimumSave % payload.step !== 0) return 'invalid';
      return (response.save as number) >= rubric.minimumSave ? 'met' : 'review';
    }
    // M2 (GAP-FIX-R5): PAE within a tolerance, ordered items, or counting on (Appendix P M2, Parts 4.6 and 7.2).
    case 'math.number-line.whole.v2': return wholeLineGrade(payload, response, rubric).verdict;
    // M3 (GAP-FIX-R5): a fraction or decimal placed on the snap grid, a comparison, or two equivalent forms on one point.
    case 'math.number-line.fraction.v2': return fractionLineGrade(payload, response, rubric).verdict;
    case 'math.fraction-area.v2': {
      if (!fields(payload, ['minimumParts', 'maximumParts']) || !whole(payload.minimumParts) || !whole(payload.maximumParts)
        || payload.minimumParts < 2 || payload.maximumParts > 6 || payload.minimumParts > payload.maximumParts
        || !fields(response, ['n', 'd']) || !whole(response.n) || !whole(response.d) || response.d < payload.minimumParts
        || response.d > payload.maximumParts || response.n < 0 || response.n > response.d) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['targetNumerator', 'targetDenominator']) || !whole(rubric.targetNumerator) || !whole(rubric.targetDenominator)
        || rubric.targetDenominator < payload.minimumParts || rubric.targetDenominator > payload.maximumParts
        || rubric.targetNumerator < 0 || rubric.targetNumerator > rubric.targetDenominator) return 'invalid';
      return response.n * rubric.targetDenominator === rubric.targetNumerator * response.d ? 'met' : 'review';
    }
    case 'math.bar-model.structure.v2': {
      // M7 (GAP-FIX-R3): the learner builds the bars from the text; the model and every slot are graded.
      const quantities = barQuantities(payload);
      if (!quantities || !fields(response, ['model', 'slots']) || !barBuild(response.model, response.slots, quantities.ids)) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['model', 'slots']) || !barBuild(rubric.model, rubric.slots, quantities.ids)
        || barModelUnknown(rubric.model as string, rubric.slots as BarSlots, quantities) === null) return 'invalid';
      return sameBarBuild(response.model as string, response.slots as BarSlots, rubric.model as string, rubric.slots as BarSlots) ? 'met' : 'review';
    }
    case 'math.bar-model.answer.v2': {
      const quantities = barQuantities(payload);
      if (!quantities || !fields(response, ['value']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      // Every unknown a two- or three-quantity bar model can hold is at most twice their sum (the total of two bars).
      const bound = 2 * quantities.values.reduce((sum, value) => sum + value, 0);
      const value = Number(response.value); if (!whole(value) || value > bound) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['target']) || !whole(rubric.target) || rubric.target < 1 || rubric.target > bound) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    case 'math.schema-diagram.structure.v2': {
      // M8 (GAP-FIX-R2): the learner picks one of the four schemas; the right one is private.
      if (!schemaQuantities(payload) || !fields(response, ['schema']) || !SCHEMAS.includes(response.schema as string)) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['schema']) || !SCHEMAS.includes(rubric.schema as string)) return 'invalid';
      return response.schema === rubric.schema ? 'met' : 'review';
    }
    case 'math.schema-diagram.slots.v2': {
      // M8: the chosen schema's three slots, each holding one story quantity or the unknown.
      const quantities = schemaQuantities(payload);
      if (!quantities || !fields(response, ['schema', 'slots']) || !schemaSlots(response.schema, response.slots, quantities.ids)) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['schema', 'slots']) || !schemaSlots(rubric.schema, rubric.slots, quantities.ids)) return 'invalid';
      const given = response.slots as Record<string, string>; const key = rubric.slots as Record<string, string>;
      return response.schema === rubric.schema && Object.keys(key).every((slot) => given[slot] === key[slot]) ? 'met' : 'review';
    }
    case 'math.schema-diagram.answer.v2': {
      const quantities = schemaQuantities(payload);
      if (!quantities || !fields(response, ['value']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const value = Number(response.value);
      const [a, b] = quantities.values as [number, number];
      if (!whole(value) || value > a * b + a + b) return 'invalid';
      if (rubric === undefined) return 'valid';
      // The target must be one relation of the two story quantities: a group total, a change or comparison difference, or a rate.
      const relations = [a + b, Math.abs(a - b), a * b, ...(a % b === 0 ? [a / b] : []), ...(b % a === 0 ? [b / a] : [])];
      if (!fields(rubric, ['target']) || !whole(rubric.target) || !relations.includes(rubric.target)) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    case 'math.worked-example.v2': {
      if (!fields(payload, ['response_step_ids']) || !Array.isArray(payload.response_step_ids)
        || payload.response_step_ids.length < 2 || payload.response_step_ids.length > 3
        || payload.response_step_ids.some((id) => typeof id !== 'string' || !/^[a-z0-9][a-z0-9._:-]{2,100}$/.test(id))
        || new Set(payload.response_step_ids).size !== payload.response_step_ids.length
        || !fields(response, ['values']) || !record(response.values)) return 'invalid';
      const ids = payload.response_step_ids as string[];
      const values = response.values;
      if (Object.keys(values).length !== ids.length || ids.some((id) => typeof values[id] !== 'string'
        || (values[id] as string).trim().length === 0 || (values[id] as string).trim().length > 40)) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['expectedValues'])) return 'invalid';
      const expectedValues = rubric.expectedValues;
      if (!record(expectedValues) || Object.keys(expectedValues).length !== ids.length
        || ids.some((id) => typeof expectedValues[id] !== 'string'
          || (expectedValues[id] as string).trim().length === 0
          || (expectedValues[id] as string).trim().length > 40)) return 'invalid';
      return ids.every((id) => sameAnswer(values[id] as string, expectedValues[id] as string)) ? 'met' : 'review';
    }
      case 'math.function-machine.v2': {
        if (!fields(payload, ['multiplierMaximum', 'offsetMaximum', 'exampleInputs']) || !whole(payload.multiplierMaximum)
          || payload.multiplierMaximum < 1 || payload.multiplierMaximum > 12 || !whole(payload.offsetMaximum)
          || payload.offsetMaximum < 0 || payload.offsetMaximum > 100 || !Array.isArray(payload.exampleInputs)
          || payload.exampleInputs.length < 3 || payload.exampleInputs.length > 5
          || payload.exampleInputs.some((input) => !whole(input) || input < 0 || input > 12)
          || new Set(payload.exampleInputs).size !== payload.exampleInputs.length || !fields(response, ['multiplier', 'offset'])
        || typeof response.multiplier !== 'string' || typeof response.offset !== 'string'
        || !/^(0|[1-9]\d*)$/.test(response.multiplier) || !/^(0|[1-9]\d*)$/.test(response.offset)) return 'invalid';
        const exampleInputs = payload.exampleInputs as number[];
        const multiplier = Number(response.multiplier); const offset = Number(response.offset);
      if (!whole(multiplier) || multiplier < 1 || multiplier > payload.multiplierMaximum
        || !whole(offset) || offset < 0 || offset > payload.offsetMaximum) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['multiplier', 'offset', 'heldOutInputs']) || !whole(rubric.multiplier)
        || rubric.multiplier < 1 || rubric.multiplier > payload.multiplierMaximum || !whole(rubric.offset)
        || rubric.offset < 0 || rubric.offset > payload.offsetMaximum || !Array.isArray(rubric.heldOutInputs)
        || rubric.heldOutInputs.length < 2 || rubric.heldOutInputs.length > 4
          || rubric.heldOutInputs.some((input) => !whole(input) || input < 0 || input > 24)
          || new Set(rubric.heldOutInputs).size !== rubric.heldOutInputs.length
          || rubric.heldOutInputs.some((input) => exampleInputs.includes(input))) return 'invalid';
      const expectedMultiplier = rubric.multiplier;
      const expectedOffset = rubric.offset;
      const heldOutInputs = rubric.heldOutInputs;
      return heldOutInputs.every((input) => multiplier * input + offset === expectedMultiplier * input + expectedOffset) ? 'met' : 'review';
    }
    case 'math.cpa-count.v2': {
      if (!fields(payload, ['left', 'right']) || !whole(payload.left) || !whole(payload.right)
        || payload.left < 1 || payload.right < 1 || payload.left > 20 || payload.right > 20
        || !fields(response, ['value']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)) return 'invalid';
      const value = Number(response.value);
      if (!whole(value) || value < 0 || value > payload.left + payload.right) return 'invalid';
      if (rubric === undefined) return 'valid';
      if (!fields(rubric, ['target']) || !whole(rubric.target) || rubric.target !== payload.left + payload.right) return 'invalid';
      return value === rubric.target ? 'met' : 'review';
    }
    case 'reasoning.decide-justify.v2': {
      const choice = reasoningResponse(payload, response);
      if (!choice) return 'invalid';
      if (rubric === undefined) return 'valid';
      const key = reasoningRubric(payload, rubric);
      if (!key) return 'invalid';
      return key.acceptableChoiceIds.includes(choice.choice) ? 'met' : 'review';
    }
    default: return scoreV2Extended(kind, payload, response, rubric);
  }
}

const REASONING_ID = /^[a-z0-9][a-z0-9._:-]{2,100}$/;
const JUDGMENT_QUALITIES: readonly V2JudgmentQuality[] = ['sound', 'partial', 'unsupported'];

function reasoningIds(value: unknown, minimum: number, maximum: number): value is string[] {
  return Array.isArray(value) && value.length >= minimum && value.length <= maximum
    && value.every((id) => typeof id === 'string' && REASONING_ID.test(id)) && new Set(value).size === value.length;
}

function reasoningResponse(payload: unknown, response: unknown): { choice: string; reason: string } | null {
  if (!fields(payload, ['choiceIds', 'reasonIds']) || !reasoningIds(payload.choiceIds, 2, 4) || !reasoningIds(payload.reasonIds, 3, 5)
    || payload.choiceIds.some((id) => (payload.reasonIds as string[]).includes(id))
    || !fields(response, ['choice', 'reason']) || typeof response.choice !== 'string' || typeof response.reason !== 'string'
    || !payload.choiceIds.includes(response.choice) || !payload.reasonIds.includes(response.reason)) return null;
  return { choice: response.choice, reason: response.reason };
}

/**
 * A reasoning rubric must be able to disagree with correctness, or the
 * judgment is correctness in disguise (Appendix C Stage 3): at least one
 * decision is not acceptable, every offered reason is classified, and the
 * reasons include at least one sound and one unsupported option.
 */
function reasoningRubric(payload: unknown, rubric: unknown): { acceptableChoiceIds: string[]; reasonQuality: Record<string, V2JudgmentQuality> } | null {
  if (!fields(payload, ['choiceIds', 'reasonIds']) || !reasoningIds(payload.choiceIds, 2, 4) || !reasoningIds(payload.reasonIds, 3, 5)
    || !fields(rubric, ['acceptableChoiceIds', 'reasonQuality']) || !reasoningIds(rubric.acceptableChoiceIds, 1, 3)
    || rubric.acceptableChoiceIds.length >= payload.choiceIds.length
    || rubric.acceptableChoiceIds.some((id) => !(payload.choiceIds as string[]).includes(id))
    || !record(rubric.reasonQuality)) return null;
  const quality = rubric.reasonQuality;
  const reasonIds = payload.reasonIds;
  if (Object.keys(quality).length !== reasonIds.length
    || reasonIds.some((id) => typeof quality[id] !== 'string' || !JUDGMENT_QUALITIES.includes(quality[id] as V2JudgmentQuality))) return null;
  const values = reasonIds.map((id) => quality[id]);
  if (!values.includes('sound') || !values.includes('unsupported')) return null;
  return { acceptableChoiceIds: rubric.acceptableChoiceIds, reasonQuality: quality as Record<string, V2JudgmentQuality> };
}

/**
 * The judgment quality of one reasoning response, independent of whether the
 * decision was acceptable. Only the reasoning family has a judgment; every
 * other kind, and any malformed input, is 'invalid'.
 */
export function scoreV2Judgment(kind: V2VisualKind, payload: unknown, response: unknown, rubric: unknown): V2JudgmentQuality | 'invalid' {
  if (kind !== 'reasoning.decide-justify.v2') return 'invalid';
  const answer = reasoningResponse(payload, response);
  const key = reasoningRubric(payload, rubric);
  if (!answer || !key) return 'invalid';
  return key.reasonQuality[answer.reason] ?? 'invalid';
}

/* ── GAP-FIX-R1 learning: locale numbers, extended scorers, diagnostics ──── */

/**
 * Appendix P Part 5 / Bible 05 §5: one pure parser for typed numbers in the
 * three launch locales. en-US and es-MX write 1,234.5; pt-BR writes 1.234,5.
 * A thousands separator must group by three; anything ambiguous is refused
 * (null) rather than guessed. The browser submits the canonical string
 * (`-?digits(.digits)?`) and echoes it before Check; Core compares values,
 * never raw text.
 */
export type V2NumberLocale = 'en-US' | 'es-MX' | 'pt-BR';
export function parseLocaleNumber(text: string, locale: V2NumberLocale): string | null {
  if (typeof text !== 'string') return null;
  const trimmed = text.trim().replace(/ | /g, ' ');
  if (trimmed.length === 0 || trimmed.length > 40) return null;
  const negative = trimmed.startsWith('-') || trimmed.startsWith('−');
  const body = negative ? trimmed.slice(1).trim() : trimmed;
  const pattern = locale === 'pt-BR'
    ? /^(\d{1,3}(?:[. ]\d{3})+|\d+)(?:,(\d+))?$/
    : /^(\d{1,3}(?:[, ]\d{3})+|\d+)(?:\.(\d+))?$/;
  const match = pattern.exec(body);
  if (!match) return null;
  const integer = match[1]!.replace(/[., ]/g, '').replace(/^0+(?=\d)/, '');
  const fraction = (match[2] ?? '').replace(/0+$/, '');
  const canonical = fraction ? `${integer}.${fraction}` : integer;
  return negative && canonical !== '0' ? `-${canonical}` : canonical;
}

/** An exact rational from a canonical decimal (`-?d+(.d+)?`) or a fraction (`-?d+/d+`). */
function rational(text: string): { n: bigint; d: bigint } | null {
  const value = text.trim();
  const fraction = /^(-?)(\d{1,15})\/(\d{1,15})$/.exec(value);
  if (fraction) {
    const d = BigInt(fraction[3]!);
    if (d === 0n) return null;
    return { n: BigInt(fraction[2]!) * (fraction[1] ? -1n : 1n), d };
  }
  const decimal = /^(-?)(\d{1,15})(?:\.(\d{1,12}))?$/.exec(value);
  if (!decimal) return null;
  const places = decimal[3]?.length ?? 0;
  const n = BigInt(`${decimal[2]}${decimal[3] ?? ''}`) * (decimal[1] ? -1n : 1n);
  return { n, d: 10n ** BigInt(places) };
}

/** Part 7.2: a semantic comparison. Numbers compare as exact rationals; anything else as case-folded text. */
export function sameAnswer(given: string, expected: string): boolean {
  const left = rational(given);
  const right = rational(expected);
  if (left && right) return left.n * right.d === right.n * left.d;
  return given.trim().toLocaleLowerCase('en-US') === expected.trim().toLocaleLowerCase('en-US');
}

/**
 * L1 selection-task codes (GAP-FIX-R3; Appendix P L1, Part 4.5), read from
 * the private card roles against "if P then Q" (the right set is P and not-Q):
 *   confirmation_bias      {P, Q}: looked for cases that agree with the rule;
 *   p_only_missing_not_q   {P}: checked the rule's case, missed the not-Q card;
 *   matching               {Q}: picked the card that matches the rule's words;
 *   not_p_checked          any other set with not-P (e.g. {P, not-P}): turned a card that cannot break the rule;
 *   all_cards              every card: no selection.
 * Any other wrong set keeps the generic partial / miss / false_alarm.
 */
export const V2_SELECTION_CODES = ['confirmation_bias', 'p_only_missing_not_q', 'matching', 'not_p_checked', 'all_cards'] as const;

/**
 * Appendix P Part 4.5: a closed diagnostic vocabulary stored beside each
 * verdict. `structure`, `path` and `bin` are structure errors (the learner
 * built the wrong model); every other non-`none` code is an answer error.
 */
/**
 * GAP-FIX-R4 (Appendix P L5 and L10): `occupancy` (the regions marked as
 * holding something) and `conclusion` (the syllogism's necessarily / possibly
 * / never) are answer errors; `rule_switch` (the first rule sorted right, the
 * items after the switch sorted wrong) is a structure error.
 */
export const V2_REASONING_CODES = ['occupancy', 'conclusion', 'rule_switch'] as const;
export const V2_DIAGNOSTIC_CODES = ['none', 'structure', 'value', 'partial', 'miss', 'false_alarm', 'path', 'outcome', 'bin', 'reason', 'tolerance', 'count_from_zero',
  ...V2_SELECTION_CODES, ...V2_REASONING_CODES] as const;
export type V2Diagnostic = (typeof V2_DIAGNOSTIC_CODES)[number];
export function v2DiagnosticFamily(code: V2Diagnostic): 'structure' | 'answer' | null {
  return code === 'none' ? null : code === 'structure' || code === 'path' || code === 'bin' || code === 'rule_switch' ? 'structure' : 'answer';
}

/** Signal-detection counts for the scam families (Part 7: hits, false alarms, d′). */
export interface V2Detection { hits: number; misses: number; false_alarms: number; correct_rejections: number }

/** d′ with the log-linear correction (0.5 added to each cell), so a perfect sort stays finite. */
export function dPrime(value: V2Detection): number {
  const hitRate = (value.hits + 0.5) / (value.hits + value.misses + 1);
  const faRate = (value.false_alarms + 0.5) / (value.false_alarms + value.correct_rejections + 1);
  return Math.round((probit(hitRate) - probit(faRate)) * 1000) / 1000;
}

function probit(p: number): number {
  // Acklam's rational approximation of the inverse normal CDF.
  const a = [-39.69683028665376, 220.9460984245205, -275.9285104469687, 138.357751867269, -30.66479806614716, 2.506628277459239];
  const b = [-54.47609879822406, 161.5858368580409, -155.6989798598866, 66.80131188771972, -13.28068155288572];
  const c = [-0.007784894002430293, -0.3223964580411365, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [0.007784695709041462, 0.3224671290700398, 2.445134137142996, 3.754408661907416];
  const tail = (q: number) => (((((c[0]! * q + c[1]!) * q + c[2]!) * q + c[3]!) * q + c[4]!) * q + c[5]!) / ((((d[0]! * q + d[1]!) * q + d[2]!) * q + d[3]!) * q + 1);
  if (p < 0.02425) return tail(Math.sqrt(-2 * Math.log(p)));
  if (p > 1 - 0.02425) return -tail(Math.sqrt(-2 * Math.log(1 - p)));
  const q = p - 0.5; const r = q * q;
  return (((((a[0]! * r + a[1]!) * r + a[2]!) * r + a[3]!) * r + a[4]!) * r + a[5]!) * q / (((((b[0]! * r + b[1]!) * r + b[2]!) * r + b[3]!) * r + b[4]!) * r + 1);
}

/** L12 / $11 (GAP-FIX-R2): which cues the learner ticked against the key; a diagnostic that never changes d′ or the score. */
export interface V2CueHits { hits: number; missed: number; false_ticks: number }
export interface V2Grade {
  verdict: V2VisualVerdict; diagnostic: V2Diagnostic; detection?: V2Detection; cues?: V2CueHits;
  /** M2/M3 (GAP-FIX-R5, Appendix P Part 4.6): the largest placement error as a share of the line, four decimals. */
  pae?: number;
}

const NUMBER_TEXT = /^-?(0|[1-9]\d*)(\.\d+)?$/;
function numberText(value: unknown): value is string { return typeof value === 'string' && value.length <= 40 && NUMBER_TEXT.test(value); }
function strings(value: unknown, min: number, max: number): value is string[] {
  return Array.isArray(value) && value.length >= min && value.length <= max && value.every((item) => typeof item === 'string' && REASONING_ID.test(item))
    && new Set(value).size === value.length;
}
function onGrid(value: unknown, minimum: number, maximum: number, step: number): value is number {
  return whole(value) && whole(minimum) && whole(maximum) && whole(step) && step > 0 && value >= minimum && value <= maximum && (value - minimum) % step === 0;
}
/**
 * The rule-checker's private roles, when the rubric carries them: every card
 * has exactly one role, the rule has a P and a not-Q card, and the cards that
 * must be turned are exactly the P and not-Q cards. Anything else is a
 * malformed rubric. `null` = an older rubric without roles (generic codes).
 */
function ruleCardRoles(rubric: Record<string, unknown>, cards: string[], need: Set<string>): Record<string, string> | null | 'invalid' {
  if (rubric.roles === undefined) return null;
  const roles = rubric.roles;
  if (!record(roles) || Object.keys(roles).length !== cards.length || cards.some((card) => !['p', 'not_p', 'q', 'not_q'].includes(roles[card] as string))) return 'invalid';
  const values = cards.map((card) => roles[card] as string);
  if (!values.includes('p') || !values.includes('not_q')) return 'invalid';
  const breakers = cards.filter((card) => roles[card] === 'p' || roles[card] === 'not_q');
  if (breakers.length !== need.size || breakers.some((card) => !need.has(card))) return 'invalid';
  return roles as Record<string, string>;
}

/** Maps a wrong flipped set, by role, to its closed selection-task code (null: no named pattern). */
export function selectionDiagnostic(flippedRoles: string[], everyCard: boolean): (typeof V2_SELECTION_CODES)[number] | null {
  if (everyCard) return 'all_cards';
  const set = new Set(flippedRoles);
  const only = (...wanted: string[]) => set.size === wanted.length && wanted.every((role) => set.has(role));
  if (only('p', 'q')) return 'confirmation_bias';
  if (only('p')) return 'p_only_missing_not_q';
  if (only('q')) return 'matching';
  if (set.has('not_p')) return 'not_p_checked';
  return null;
}

const grade = (verdict: V2VisualVerdict, diagnostic: V2Diagnostic = verdict === 'met' ? 'none' : 'value'): V2Grade => ({ verdict, diagnostic });
const INVALID: V2Grade = { verdict: 'invalid', diagnostic: 'none' };

function compoundMinor(principal: number, rateBps: number, years: number): number | null {
  if (!whole(principal) || principal < 100 || principal > 1_000_000 || !whole(rateBps) || rateBps < 100 || rateBps > 1_500 || !whole(years) || years < 1 || years > 30) return null;
  let value = BigInt(principal);
  for (let year = 0; year < years; year += 1) value = (value * BigInt(10_000 + rateBps) + 5_000n) / 10_000n;
  return value > BigInt(Number.MAX_SAFE_INTEGER) ? null : Number(value);
}

function taxOwed(income: number, brackets: unknown): { tax: number; marginal: number; average: number } | null {
  if (!Array.isArray(brackets) || brackets.length < 2 || brackets.length > 6) return null;
  let lower = 0; let tax = 0; let marginal = 0;
  for (const [index, bracket] of brackets.entries()) {
    if (!record(bracket) || !whole(bracket.rateBasisPoints) || bracket.rateBasisPoints < 0 || bracket.rateBasisPoints > 10_000) return null;
    const upper = bracket.upToMinor;
    if (upper === null ? index !== brackets.length - 1 : !whole(upper) || upper <= lower) return null;
    const taxable = Math.max(0, Math.min(income, (upper as number | null) ?? income) - lower);
    tax += Math.round(taxable * bracket.rateBasisPoints / 10_000);
    if (taxable > 0) marginal = bracket.rateBasisPoints;
    if (upper === null) break;
    lower = upper as number;
  }
  // M20 (GAP-FIX-R5): the average rate, rounded basis points of tax / income (the model's own rounding).
  return { tax, marginal, average: income === 0 ? 0 : Math.round(tax * 10_000 / income) };
}

type RuleLink = 'and' | 'or' | 'none';
type RuleComparator = '>=' | '>' | '<=' | '<';
function ruleOutcome(saved: number, goalDay: boolean, comparator: RuleComparator, threshold: number, link: RuleLink): boolean {
  const amount = comparator === '>=' ? saved >= threshold : comparator === '>' ? saved > threshold : comparator === '<=' ? saved <= threshold : saved < threshold;
  return link === 'and' ? amount && goalDay : link === 'or' ? amount || goalDay : amount;
}
const COMPARATORS: readonly string[] = ['>=', '>', '<=', '<'];
const LINKS: readonly string[] = ['and', 'or', 'none'];

function money(payload: Record<string, unknown>, response: unknown): number | null {
  const denominations = payload.denominations;
  if (!Array.isArray(denominations) || denominations.length < 2 || denominations.length > 8 || !fields(response, ['counts']) || !record(response.counts)) return null;
  const counts = response.counts;
  if (Object.keys(counts).length !== denominations.length) return null;
  let total = 0;
  for (const denomination of denominations) {
    if (!record(denomination) || !whole(denomination.value) || denomination.value <= 0 || !whole(denomination.available)) return null;
    const count = counts[String(denomination.value)];
    // Conservation: a tray never holds more pieces than it has, nor fewer than none.
    if (!whole(count) || count < 0 || count > denomination.available) return null;
    total += count * denomination.value;
  }
  return total;
}

function fewestPieces(target: number, denominations: Array<{ value: number; available: number }>): number | null {
  const best = new Array<number>(target + 1).fill(Infinity);
  best[0] = 0;
  for (const { value, available } of denominations) {
    for (let used = 0; used < available; used += 1) {
      for (let amount = target; amount >= value; amount -= 1) {
        const candidate = best[amount - value]! + 1;
        if (candidate < best[amount]!) best[amount] = candidate;
      }
    }
  }
  return Number.isFinite(best[target]!) ? best[target]! : null;
}

function flowPath(payload: Record<string, unknown>, path: unknown): path is string[] {
  if (!Array.isArray(path) || path.length < 2 || path.length > 12 || typeof payload.start !== 'string' || path[0] !== payload.start || !Array.isArray(payload.nodes)) return false;
  const nodes = new Map<string, Record<string, unknown>>();
  for (const node of payload.nodes) if (record(node) && typeof node.id === 'string') nodes.set(node.id, node);
  for (let index = 0; index < path.length; index += 1) {
    const node = typeof path[index] === 'string' ? nodes.get(path[index] as string) : undefined;
    if (!node) return false;
    const next = path[index + 1];
    if (next === undefined) return node.yes === undefined && node.no === undefined;
    if (next !== node.yes && next !== node.no) return false;
  }
  return false;
}

function choiceGrade(payload: unknown, response: unknown, rubric: unknown, maximum: number, maxChoices = 3): V2Grade {
  if (!fields(payload, ['choiceIds']) || !strings(payload.choiceIds, 2, maxChoices) || !fields(response, ['choice']) || typeof response.choice !== 'string'
    || !payload.choiceIds.includes(response.choice)) return INVALID;
  if (rubric === undefined) return grade('valid');
  if (!fields(rubric, ['acceptable_choice_ids']) || !strings(rubric.acceptable_choice_ids, 1, maximum)
    || rubric.acceptable_choice_ids.some((choice) => !(payload.choiceIds as string[]).includes(choice))) return INVALID;
  return rubric.acceptable_choice_ids.includes(response.choice) ? grade('met') : grade('review', 'outcome');
}

/**
 * L10 / $10: each item's (bin, reason) against its accepted pairs. With a rule
 * switch (GAP-FIX-R4, Appendix P L10 "the rule changes mid-task"), items from
 * `switchAfter` on belong to the second bin set, and each phase is graded:
 * a first phase sorted right with a wrong bin after the switch is `rule_switch`.
 */
function sortGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  const switched = record(payload) && Object.hasOwn(payload, 'switchAfter');
  if (!fields(payload, switched ? ['binIds', 'itemIds', 'reasonIds', 'switchAfter', 'secondBinIds'] : ['binIds', 'itemIds', 'reasonIds'])
    || !strings(payload.binIds, 2, 4) || !strings(payload.itemIds, 2, 8) || !strings(payload.reasonIds, 2, 5)
    || !fields(response, ['placements']) || !record(response.placements)) return INVALID;
  const { binIds, itemIds, reasonIds } = payload as { binIds: string[]; itemIds: string[]; reasonIds: string[] };
  const switchAt = switched ? (payload as { switchAfter: unknown }).switchAfter : itemIds.length;
  const secondBins = switched ? (payload as { secondBinIds: unknown }).secondBinIds : [];
  if (!whole(switchAt) || switchAt < 1 || switchAt > itemIds.length || (switched && (switchAt >= itemIds.length || !strings(secondBins, 2, 4)))) return INVALID;
  if (new Set([...binIds, ...(secondBins as string[])]).size !== binIds.length + (secondBins as string[]).length) return INVALID;
  const phaseBins = (index: number) => (index >= switchAt ? secondBins as string[] : binIds);
  const placements = response.placements;
  if (Object.keys(placements).length !== itemIds.length) return INVALID;
  for (const [index, item] of itemIds.entries()) {
    const placed = placements[item];
    if (!fields(placed, ['bin', 'reason']) || typeof placed.bin !== 'string' || typeof placed.reason !== 'string'
      || !phaseBins(index).includes(placed.bin) || !reasonIds.includes(placed.reason)) return INVALID;
  }
  if (rubric === undefined) return grade('valid');
  if (!fields(rubric, ['accepted']) || !record(rubric.accepted) || Object.keys(rubric.accepted).length !== itemIds.length) return INVALID;
  const accepted = rubric.accepted;
  const miss = [{ bin: false, reason: false }, { bin: false, reason: false }];
  for (const [index, item] of itemIds.entries()) {
    const pairs = accepted[item];
    if (!Array.isArray(pairs) || pairs.length < 1 || pairs.length > 4 || pairs.some((pair) => !fields(pair, ['bin', 'reason'])
      || !phaseBins(index).includes(pair.bin as string) || !reasonIds.includes(pair.reason as string))) return INVALID;
    const placed = placements[item] as { bin: string; reason: string };
    const phase = miss[index >= switchAt ? 1 : 0]!;
    const sameBin = pairs.filter((pair) => (pair as { bin: string }).bin === placed.bin);
    if (sameBin.length === 0) phase.bin = true;
    else if (!sameBin.some((pair) => (pair as { reason: string }).reason === placed.reason)) phase.reason = true;
  }
  const [first, second] = miss as [{ bin: boolean; reason: boolean }, { bin: boolean; reason: boolean }];
  if (first.bin) return grade('review', 'bin');
  if (second.bin) return grade('review', 'rule_switch');
  return first.reason || second.reason ? grade('review', 'reason') : grade('met');
}

const EULER_RELATION_IDS = ['overlap', 'subset', 'disjoint'] as const;
const EULER_CONCLUSION_IDS = ['necessarily', 'possibly', 'never'] as const;
function eulerRegionsFor(relation: string): string[] {
  // Impossible states: nothing is only-in-A when A sits inside B; nothing is in both when they never meet.
  return relation === 'subset' ? ['second', 'both', 'neither'] : relation === 'disjoint' ? ['first', 'second', 'neither'] : ['first', 'second', 'both', 'neither'];
}

/**
 * L5 (GAP-FIX-R4, Appendix P L5): graded on the item->region map, the region
 * occupancy flags and the chosen conclusion. With `chooseRelation` the learner
 * also picked the diagram: a wrong diagram is a `structure` error, graded
 * first; then the placements (`partial` / `structure`), then the occupancy
 * flags (`occupancy`), then the conclusion (`conclusion`).
 */
function eulerGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  if (!record(payload) || !strings(payload.itemIds, 2, 6)) return INVALID;
  const choose = payload.chooseRelation === true;
  const occupancy = payload.occupancy === true;
  const concluding = payload.conclusion === true;
  const payloadFields = [choose ? 'chooseRelation' : 'relation', 'itemIds', ...(occupancy ? ['occupancy'] : []), ...(concluding ? ['conclusion'] : [])];
  if (!fields(payload, payloadFields) || (!choose && !EULER_RELATION_IDS.includes(payload.relation as never))) return INVALID;
  const responseFields = ['placements', ...(choose ? ['relation'] : []), ...(occupancy ? ['occupied'] : []), ...(concluding ? ['conclusion'] : [])];
  if (!fields(response, responseFields) || !record(response.placements)) return INVALID;
  const relation = choose ? response.relation : payload.relation;
  if (typeof relation !== 'string' || !EULER_RELATION_IDS.includes(relation as never)) return INVALID;
  const items = payload.itemIds as string[];
  const placements = response.placements;
  const allowed = eulerRegionsFor(relation);
  if (Object.keys(placements).length !== items.length || items.some((item) => typeof placements[item] !== 'string' || !allowed.includes(placements[item] as string))) return INVALID;
  const regionSet = (value: unknown, regions: string[]) => Array.isArray(value) && value.length <= regions.length && new Set(value).size === value.length
    && value.every((region) => typeof region === 'string' && regions.includes(region));
  if (occupancy && !regionSet(response.occupied, allowed)) return INVALID;
  if (concluding && !EULER_CONCLUSION_IDS.includes(response.conclusion as never)) return INVALID;
  if (rubric === undefined) return grade('valid');
  const rubricFields = ['regions', ...(choose ? ['relation'] : []), ...(occupancy ? ['occupied'] : []), ...(concluding ? ['conclusion'] : [])];
  if (!fields(rubric, rubricFields) || !record(rubric.regions) || Object.keys(rubric.regions).length !== items.length) return INVALID;
  const keyRelation = choose ? rubric.relation : payload.relation;
  if (typeof keyRelation !== 'string' || !EULER_RELATION_IDS.includes(keyRelation as never)) return INVALID;
  const keyAllowed = eulerRegionsFor(keyRelation);
  const regions = rubric.regions;
  if (items.some((item) => !keyAllowed.includes(regions[item] as string))) return INVALID;
  // A region holding an item is occupied: the key's flags must include every region its items sit in.
  if (occupancy && (!regionSet(rubric.occupied, keyAllowed) || items.some((item) => !(rubric.occupied as string[]).includes(regions[item] as string)))) return INVALID;
  if (concluding && !EULER_CONCLUSION_IDS.includes(rubric.conclusion as never)) return INVALID;
  if (choose && relation !== keyRelation) return grade('review', 'structure');
  const wrong = items.filter((item) => placements[item] !== regions[item]).length;
  if (wrong > 0) return grade('review', wrong < items.length ? 'partial' : 'structure');
  if (occupancy) {
    const marked = new Set(response.occupied as string[]);
    const key = rubric.occupied as string[];
    if (marked.size !== key.length || key.some((region) => !marked.has(region))) return grade('review', 'occupancy');
  }
  if (concluding && response.conclusion !== rubric.conclusion) return grade('review', 'conclusion');
  return grade('met');
}

function detectionGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  const cued = fields(payload, ['messageIds', 'cueIds']);
  if ((!cued && !fields(payload, ['messageIds'])) || !strings((payload as Record<string, unknown>).messageIds, 3, 8)
    || !fields(response, cued ? ['flagged', 'cues'] : ['flagged']) || !strings(response.flagged, 0, 8)
    || response.flagged.some((flag) => !((payload as Record<string, unknown>).messageIds as string[]).includes(flag))) return INVALID;
  const messages = (payload as Record<string, unknown>).messageIds as string[];
  const cueIds = cued ? (payload as Record<string, unknown>).cueIds : [];
  if (cued && (!strings(cueIds, 2, 6) || !cueTicks(response.cues, messages, cueIds as string[]))) return INVALID;
  if (rubric === undefined) return grade('valid');
  // Genuine messages are always in the set: a key that calls everything a scam cannot measure false alarms.
  const rubricFields = record(rubric) && Object.hasOwn(rubric, 'cue_ids') ? ['scam_ids', 'cue_ids'] : ['scam_ids'];
  if (!fields(rubric, rubricFields) || !strings(rubric.scam_ids, 1, messages.length - 1) || rubric.scam_ids.some((scam) => !messages.includes(scam))) return INVALID;
  if (rubricFields.length === 2 && (!cued || !cueTicks(rubric.cue_ids, messages, cueIds as string[]))) return INVALID;
  const scams = new Set(rubric.scam_ids);
  const flagged = new Set(response.flagged as string[]);
  const detection: V2Detection = {
    hits: [...scams].filter((scam) => flagged.has(scam)).length,
    misses: [...scams].filter((scam) => !flagged.has(scam)).length,
    false_alarms: [...flagged].filter((flag) => !scams.has(flag)).length,
    correct_rejections: messages.filter((message) => !scams.has(message) && !flagged.has(message)).length,
  };
  const met = detection.misses === 0 && detection.false_alarms === 0;
  const diagnostic: V2Diagnostic = met ? 'none' : detection.misses > 0 && detection.false_alarms > 0 ? 'partial' : detection.misses > 0 ? 'miss' : 'false_alarm';
  if (rubricFields.length === 1) return { verdict: met ? 'met' : 'review', diagnostic, detection };
  // L12: "tick which cues fired" — counted beside the verdict; the score and d′ stay the flag decision alone.
  const key = rubric.cue_ids as Record<string, string[]>; const ticked = response.cues as Record<string, string[]>;
  const cues: V2CueHits = { hits: 0, missed: 0, false_ticks: 0 };
  for (const message of messages) {
    const expected = new Set(key[message] ?? []); const given = new Set(ticked[message] ?? []);
    for (const cue of given) if (expected.has(cue)) cues.hits += 1; else cues.false_ticks += 1;
    for (const cue of expected) if (!given.has(cue)) cues.missed += 1;
  }
  return { verdict: met ? 'met' : 'review', diagnostic, detection, cues };
}

/**
 * Canonical grade of one response: the verdict, a closed diagnostic code and,
 * for the detection families, the signal-detection counts. `scoreV2Visual`
 * stays the verdict-only entry point every existing caller uses.
 */
export function gradeV2Response(kind: V2VisualKind, payload: unknown, response: unknown, rubric?: unknown): V2Grade {
  const verdict = scoreV2Visual(kind, payload, response, rubric);
  if (verdict === 'invalid' || verdict === 'valid') return { verdict, diagnostic: 'none' };
  switch (kind) {
    case 'money.allocation.v2':
    case 'math.bar-model.answer.v2':
    case 'math.schema-diagram.answer.v2':
    case 'math.fraction-area.v2':
    case 'math.function-machine.v2':
    case 'math.cpa-count.v2': return grade(verdict);
    case 'math.bar-model.structure.v2':
    case 'math.schema-diagram.structure.v2': return grade(verdict, verdict === 'met' ? 'none' : 'structure');
    // M8: a slot step built on the wrong schema is a structure error; the right schema with misplaced quantities is a value error.
    case 'math.schema-diagram.slots.v2': return grade(verdict, verdict === 'met' ? 'none'
      : (response as { schema: string }).schema !== (rubric as { schema: string }).schema ? 'structure' : 'value');
    case 'math.number-line.whole.v2': return wholeLineGrade(payload, response, rubric);
    case 'math.number-line.fraction.v2': return fractionLineGrade(payload, response, rubric);
    case 'reasoning.decide-justify.v2': return grade(verdict, verdict === 'met' ? 'none' : 'outcome');
    case 'math.worked-example.v2': {
      if (verdict === 'met') return grade('met');
      const values = (response as { values: Record<string, string> }).values;
      const expected = (rubric as { expectedValues: Record<string, string> }).expectedValues;
      const right = Object.keys(expected).filter((key) => sameAnswer(values[key]!, expected[key]!)).length;
      return grade('review', right > 0 ? 'partial' : 'value');
    }
    default: return scoreV2ExtendedDetailed(kind, payload, response, rubric);
  }
}


/* ── M2 and M3 number lines (GAP-FIX-R2, GAP-FIX-R5) ─────────────────────────── */

/*
 * Appendix P M2 grades "position error as a share of the line (PAE) within a
 * tolerance; order of placed items"; M3 grades "placement error; comparison
 * choice; equivalents land on one point"; Part 7.2 names the rubric
 * `{ target, tolerance, snap }` (the snap is the payload's step or divisions).
 * Everything is compared in whole numbers: a tolerance share is whole basis
 * points of the line, and fractions and decimals are exact rationals.
 */

/** A tolerance share of the line (0 to 0.2, at most four decimals) as whole basis points; absent = exact. */
function toleranceBps(value: unknown): number | null {
  if (value === undefined) return 0;
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value > 0.2) return null;
  const bps = Math.round(value * 10_000);
  return Math.abs(value * 10_000 - bps) < 1e-6 ? bps : null;
}
/** |value - target| / span <= bps / 10000, in whole numbers. */
function withinShare(value: number, target: number, span: number, bps: number): boolean { return Math.abs(value - target) * 10_000 <= bps * span; }
/** PAE to four decimals, for the receipt. */
function paeOf(value: number, target: number, span: number): number { return Math.round(Math.abs(value - target) * 10_000 / span) / 10_000; }
/** Only these keys, the required ones present. */
function keysIn(value: unknown, required: readonly string[], optional: readonly string[] = []): value is Record<string, unknown> {
  return record(value) && required.every((name) => Object.hasOwn(value, name)) && Object.keys(value).every((name) => required.includes(name) || optional.includes(name));
}
const WHOLE_TEXT = /^(0|[1-9]\d{0,5})$/;
const LINE_ITEM = /^[a-z0-9][a-z0-9._:-]{2,100}$/;

/** M2: one point, several ordered items, or counting on from the current square (GAP-FIX-R2). */
function wholeLineGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  if (fields(payload, ['minimum', 'maximum', 'step', 'initial', 'hops'])) return countOnGrade(payload, response, rubric);
  const itemIds = record(payload) && Object.hasOwn(payload, 'itemIds') ? payload.itemIds : undefined;
  if (!(itemIds === undefined ? fields(payload, ['minimum', 'maximum', 'step']) : fields(payload, ['minimum', 'maximum', 'step', 'itemIds']))) return INVALID;
  const { minimum, maximum, step } = payload as Record<string, unknown>;
  if (!whole(minimum) || minimum < 0 || !whole(maximum) || maximum <= minimum || !whole(step) || step <= 0 || (maximum - minimum) % step !== 0) return INVALID;
  const span = maximum - minimum;
  const point = (text: unknown): number | null => typeof text === 'string' && WHOLE_TEXT.test(text) && onGrid(Number(text), minimum, maximum, step) ? Number(text) : null;
  if (itemIds === undefined) {
    if (!fields(response, ['value'])) return INVALID;
    const value = point(response.value);
    if (value === null) return INVALID;
    if (rubric === undefined) return grade('valid');
    if (!keysIn(rubric, ['target'], ['tolerance_share']) || !onGrid(rubric.target, minimum, maximum, step)) return INVALID;
    const bps = toleranceBps(rubric.tolerance_share);
    if (bps === null) return INVALID;
    const pae = paeOf(value, rubric.target, span);
    return withinShare(value, rubric.target, span, bps) ? { ...grade('met'), pae } : { ...grade('review', 'tolerance'), pae };
  }
  // Ordered items: every item placed on the grid; the order of the placed values first, then each one's PAE.
  if (!Array.isArray(itemIds) || itemIds.length < 2 || itemIds.length > 4 || !itemIds.every((item) => typeof item === 'string' && LINE_ITEM.test(item))
    || new Set(itemIds).size !== itemIds.length || !fields(response, ['placements']) || !fields(response.placements, itemIds as string[])) return INVALID;
  const ids = itemIds as string[];
  const placed = ids.map((item) => point((response.placements as Record<string, unknown>)[item]));
  if (placed.some((value) => value === null)) return INVALID;
  if (rubric === undefined) return grade('valid');
  if (!keysIn(rubric, ['targets'], ['tolerance_share']) || !fields(rubric.targets, ids)) return INVALID;
  const targets = ids.map((item) => (rubric.targets as Record<string, unknown>)[item]);
  const bps = toleranceBps(rubric.tolerance_share);
  if (bps === null || !targets.every((target) => onGrid(target, minimum, maximum, step)) || new Set(targets).size !== targets.length) return INVALID;
  const values = placed as number[]; const keys = targets as number[];
  // Order: every pair the key orders must be placed in the same strict order.
  const ordered = keys.every((a, i) => keys.every((b, j) => a >= b || values[i]! < values[j]!));
  const pae = Math.max(...values.map((value, index) => paeOf(value, keys[index]!, span)));
  if (!ordered) return { ...grade('review', 'structure'), pae };
  return values.every((value, index) => withinShare(value, keys[index]!, span, bps)) ? { ...grade('met'), pae } : { ...grade('review', 'tolerance'), pae };
}

/** M2 / $2 counting on (GAP-FIX-R2): the point is where the hops from the current square land; the target is exact. */
function countOnGrade(payload: Record<string, unknown>, response: unknown, rubric: unknown): V2Grade {
  const { minimum, maximum, step, initial, hops } = payload as Record<string, unknown>;
  if (!whole(minimum) || minimum < 0 || !whole(maximum) || maximum <= minimum || !whole(step) || step <= 0 || !onGrid(initial, minimum, maximum, step)
    || !Array.isArray(hops) || hops.length < 1 || hops.length > 3 || hops.some((hop) => !whole(hop) || hop <= 0 || hop % step !== 0)
    || !fields(response, ['value', 'hops']) || typeof response.value !== 'string' || !/^(0|[1-9]\d*)$/.test(response.value)
    || !Array.isArray(response.hops) || response.hops.length < 1 || response.hops.length > 40
    || response.hops.some((hop) => !(hops as number[]).includes(hop as number))) return INVALID;
  const value = Number(response.value);
  // Conservation: the point is always where the hops from the current square land.
  const landed = (response.hops as number[]).reduce((sum, hop) => sum + hop, initial);
  if (value !== landed || value > maximum) return INVALID;
  if (rubric === undefined) return grade('valid');
  if (!fields(rubric, ['target']) || !onGrid(rubric.target, initial, maximum, step) || rubric.target === initial) return INVALID;
  const pae = paeOf(value, rubric.target, maximum - minimum);
  return value === rubric.target ? { ...grade('met'), pae } : { ...grade('review', 'tolerance'), pae };
}

const LINE_NUMBER = /^((0|[1-9]\d{0,2})\/([1-9]\d{0,2})|(0|[1-9]\d{0,2})(\.\d{1,6})?)$/;
/**
 * A fraction ("3/4") or canonical decimal ("0.75") as whole snap units on a
 * 0..maximumWhole line cut into `divisions` per whole; null when it is not a
 * number, is off the line or falls between two snap points. The browser sends
 * a typed decimal already parsed for its locale (`parseLocaleNumber`).
 */
export function lineUnits(text: unknown, maximumWhole: number, divisions: number): number | null {
  if (typeof text !== 'string' || !LINE_NUMBER.test(text)) return null;
  const value = rational(text);
  if (!value || value.n < 0n || value.n * BigInt(divisions) % value.d !== 0n) return null;
  const units = Number(value.n * BigInt(divisions) / value.d);
  return units <= maximumWhole * divisions ? units : null;
}
const COMPARE_CHOICES = ['first', 'second', 'same'];

/** M3: one placement, a comparison of two numbers, or two equivalent forms that must land on one point. */
function fractionLineGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  if (!keysIn(payload, ['maximumWhole', 'divisions'], ['compare_values', 'equivalent_values']) || (payload.maximumWhole !== 1 && payload.maximumWhole !== 2)
    || !whole(payload.divisions) || payload.divisions < 2 || payload.divisions > 12
    || (Object.hasOwn(payload, 'compare_values') && Object.hasOwn(payload, 'equivalent_values'))) return INVALID;
  const maximumWhole = payload.maximumWhole as number; const divisions = payload.divisions;
  const total = maximumWhole * divisions;
  const units = (text: unknown) => lineUnits(text, maximumWhole, divisions);
  const pair = (payload.compare_values ?? payload.equivalent_values) as unknown;
  if (pair === undefined) {
    if (!fields(response, ['value'])) return INVALID;
    const value = units(response.value);
    if (value === null) return INVALID;
    if (rubric === undefined) return grade('valid');
    if (!fields(rubric, ['targetNumerator', 'targetDenominator', 'toleranceUnits']) || !whole(rubric.targetNumerator) || rubric.targetNumerator < 0
      || !whole(rubric.targetDenominator) || rubric.targetDenominator <= 0 || !whole(rubric.toleranceUnits) || rubric.toleranceUnits < 0 || rubric.toleranceUnits > 2) return INVALID;
    const target = units(`${rubric.targetNumerator}/${rubric.targetDenominator}`);
    if (target === null) return INVALID;
    const pae = paeOf(value, target, total);
    return Math.abs(value - target) <= rubric.toleranceUnits ? { ...grade('met'), pae } : { ...grade('review', 'tolerance'), pae };
  }
  // Both numbers are public (they are the question) and must sit on the snap grid.
  if (!Array.isArray(pair) || pair.length !== 2) return INVALID;
  const targets = pair.map(units);
  if (targets.some((value) => value === null)) return INVALID;
  const [a, b] = targets as [number, number];
  const comparing = Object.hasOwn(payload, 'compare_values');
  if (!comparing && a !== b) return INVALID;
  if (!(comparing ? fields(response, ['placements', 'choice']) : fields(response, ['placements']))) return INVALID;
  const answer = response as Record<string, unknown>;
  if (!fields(answer.placements, ['first', 'second']) || (comparing && (typeof answer.choice !== 'string' || !COMPARE_CHOICES.includes(answer.choice)))) return INVALID;
  const first = units(answer.placements.first);
  const second = units(answer.placements.second);
  if (first === null || second === null) return INVALID;
  if (rubric === undefined) return grade('valid');
  if (!(comparing ? fields(rubric, ['choice', 'toleranceUnits']) : fields(rubric, ['toleranceUnits']))) return INVALID;
  const key = rubric as Record<string, unknown>;
  const tolerance = key.toleranceUnits;
  if (!whole(tolerance) || tolerance < 0 || tolerance > 2) return INVALID;
  const pae = Math.max(paeOf(first, a, total), paeOf(second, b, total));
  const firstRight = Math.abs(first - a) <= tolerance; const secondRight = Math.abs(second - b) <= tolerance;
  if (comparing) {
    // The key must be the true comparison of the two public numbers; anything else is a content defect.
    const truth = a > b ? 'first' : a < b ? 'second' : 'same';
    if (key.choice !== truth) return INVALID;
    if (!firstRight || !secondRight) return { ...grade('review', firstRight || secondRight ? 'partial' : 'tolerance'), pae };
    return answer.choice === truth ? { ...grade('met'), pae } : { ...grade('review', 'value'), pae };
  }
  // Equivalents: both forms within tolerance AND on one point.
  if (firstRight && secondRight && first === second) return { ...grade('met'), pae };
  return { ...grade('review', firstRight || secondRight ? 'partial' : 'tolerance'), pae };
}

/* ── $2 counting up, L12 cue ticks (GAP-FIX-R2) ─────────────────────────────── */

/** The counting-up sequence: strictly rising totals, each one coin more, the coins exactly the tray. */
function countUp(denominations: Array<{ value: number }>, counts: Record<string, number>, sequence: unknown, price: number, paid: number): 'from_price' | 'from_zero' | 'wrong' | null {
  const coins = Object.values(counts).reduce((sum, count) => sum + count, 0);
  if (!Array.isArray(sequence) || sequence.length !== coins || sequence.length > 60 || sequence.some((value) => !whole(value) || value < 0)) return null;
  const values = new Set(denominations.map((item) => item.value));
  const fits = (start: number) => {
    const used: Record<string, number> = {};
    let previous = start;
    for (const said of sequence as number[]) {
      const coin = said - previous;
      if (!values.has(coin)) return false;
      used[String(coin)] = (used[String(coin)] ?? 0) + 1;
      previous = said;
    }
    return Object.entries(counts).every(([coin, count]) => (used[coin] ?? 0) === count);
  };
  if (fits(price) && sequence.at(-1) === paid) return 'from_price';
  if (fits(0)) return 'from_zero';
  return 'wrong';
}

function cueTicks(value: unknown, messages: readonly string[], cueIds: readonly string[]): boolean {
  return record(value) && Object.keys(value).every((message) => messages.includes(message))
    && Object.values(value).every((ticks) => Array.isArray(ticks) && ticks.length <= cueIds.length && new Set(ticks).size === ticks.length
      && ticks.every((cue) => typeof cue === 'string' && cueIds.includes(cue)));
}

/* ── $6 unit prices (GAP-FIX-R2) ─────────────────────────────────────────── */

interface Offer { id: string; quantity: number; price: number }
function unitOffers(payload: unknown): { offers: Offer[]; scale: number } | null {
  if (!fields(payload, ['scale', 'offers']) || (payload.scale !== 1 && payload.scale !== 100) || !Array.isArray(payload.offers)
    || payload.offers.length < 2 || payload.offers.length > 3) return null;
  const offers: Offer[] = [];
  for (const offer of payload.offers) {
    if (!fields(offer, ['id', 'quantity', 'price']) || typeof offer.id !== 'string' || !REASONING_ID.test(offer.id)
      || !onGrid(offer.quantity, 1, 1_000, 1) || !onGrid(offer.price, 1, 1_000_000, 1)) return null;
    offers.push({ id: offer.id, quantity: offer.quantity, price: offer.price });
  }
  if (new Set(offers.map((offer) => offer.id)).size !== offers.length) return null;
  return { offers, scale: payload.scale };
}
/** Within half a hundredth of the exact unit price (major units): |g - p/(q*s)| <= 1/200. */
function nearUnitPrice(given: { n: bigint; d: bigint }, offer: Offer, scale: number): boolean {
  const qs = BigInt(offer.quantity * scale);
  const gap = given.n * qs - given.d * BigInt(offer.price);
  return (gap < 0n ? -gap : gap) * 200n <= given.d * qs;
}
function unitPriceGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  const value = unitOffers(payload);
  if (!value || !fields(response, ['unit_prices', 'choice']) || !record(response.unit_prices) || typeof response.choice !== 'string') return INVALID;
  const { offers, scale } = value;
  const typed = response.unit_prices;
  if (Object.keys(typed).length !== offers.length || !offers.some((offer) => offer.id === response.choice)) return INVALID;
  const given = offers.map((offer) => typeof typed[offer.id] === 'string' && NUMBER_TEXT.test(typed[offer.id] as string) ? rational(typed[offer.id] as string) : null);
  if (given.some((item) => item === null || item.n < 0n)) return INVALID;
  if (rubric === undefined) return grade('valid');
  // The key must state each exact unit price and the one strictly cheapest offer.
  const cheapest = offers.reduce((best, offer) => offer.price * best.quantity < best.price * offer.quantity ? offer : best);
  if (!fields(rubric, ['unit_prices', 'better_id']) || !record(rubric.unit_prices) || rubric.better_id !== cheapest.id
    || offers.some((offer) => offer !== cheapest && offer.price * cheapest.quantity === cheapest.price * offer.quantity)
    || Object.keys(rubric.unit_prices).length !== offers.length) return INVALID;
  for (const offer of offers) {
    const key = typeof (rubric.unit_prices as Record<string, unknown>)[offer.id] === 'string' ? rational((rubric.unit_prices as Record<string, string>)[offer.id]!) : null;
    if (!key || key.n * BigInt(offer.quantity * scale) !== key.d * BigInt(offer.price)) return INVALID;
  }
  const pricesRight = offers.every((offer, index) => nearUnitPrice(given[index]!, offer, scale));
  const choiceRight = response.choice === cheapest.id;
  return pricesRight && choiceRight ? grade('met') : grade('review', pricesRight ? 'outcome' : 'value');
}

/* ── L2 rule builder and L6/$9 built flowcharts (GAP-FIX-R2) ──────────────── */

type Expr = { c: string } | { not: Expr } | { and: [Expr, Expr] } | { or: [Expr, Expr] };
/** A rule expression the level allows: single = one condition; connective = one condition or A AND/OR B; nested = NOT and nesting to depth 3. */
function exprOk(value: unknown, conditions: readonly string[], level: string, depth = 0): value is Expr {
  if (!record(value) || Object.keys(value).length !== 1 || depth > 3) return false;
  if (typeof value.c === 'string') return conditions.includes(value.c);
  if (level === 'single') return false;
  if (Object.hasOwn(value, 'not')) return level === 'nested' && exprOk(value.not, conditions, level, depth + 1);
  const pair = Array.isArray(value.and) ? value.and : Array.isArray(value.or) ? value.or : null;
  if (!pair || pair.length !== 2) return false;
  if (level === 'connective') return pair.every((item) => record(item) && typeof item.c === 'string' && conditions.includes(item.c));
  return pair.every((item) => exprOk(item, conditions, level, depth + 1));
}
function evalExpr(value: Expr, facts: Record<string, boolean>): boolean {
  if ('c' in value) return facts[value.c] === true;
  if ('not' in value) return !evalExpr(value.not, facts);
  if ('and' in value) return evalExpr(value.and[0], facts) && evalExpr(value.and[1], facts);
  return evalExpr(value.or[0], facts) || evalExpr(value.or[1], facts);
}
function exprConditions(value: Expr, out = new Set<string>()): Set<string> {
  if ('c' in value) out.add(value.c);
  else if ('not' in value) exprConditions(value.not, out);
  else for (const item of 'and' in value ? value.and : value.or) exprConditions(item, out);
  return out;
}
function ruleOk(rule: unknown, conditions: readonly string[], actions: readonly string[], level: string): rule is { if: Expr; then: string; else: string } {
  return fields(rule, ['if', 'then', 'else']) && typeof rule.then === 'string' && typeof rule.else === 'string'
    && actions.includes(rule.then) && actions.includes(rule.else) && exprOk(rule.if, conditions, level) && JSON.stringify(rule.if).length <= 600;
}
function factsOk(value: unknown, keys: readonly string[]): value is Record<string, boolean> {
  return record(value) && Object.keys(value).length === keys.length && keys.every((key) => typeof value[key] === 'boolean');
}
function ruleBuilderGrade(payload: unknown, response: unknown, rubric: unknown): V2Grade {
  if (!fields(payload, ['level', 'conditionIds', 'actionIds']) || !['single', 'connective', 'nested'].includes(payload.level as string)
    || !strings(payload.conditionIds, 1, 4) || !strings(payload.actionIds, 2, 3) || !fields(response, ['rule'])) return INVALID;
  const conditions = payload.conditionIds as string[]; const actions = payload.actionIds as string[]; const level = payload.level as string;
  if (!ruleOk(response.rule, conditions, actions, level)) return INVALID;
  if (rubric === undefined) return grade('valid');
  if (!fields(rubric, ['target', 'scenarios']) || !ruleOk(rubric.target, conditions, actions, level) || rubric.target.then === rubric.target.else
    || !Array.isArray(rubric.scenarios) || rubric.scenarios.length < 5 || rubric.scenarios.length > 10
    || rubric.scenarios.some((item) => !factsOk(item, conditions))) return INVALID;
  const target = rubric.target; const learner = response.rule as { if: Expr; then: string; else: string };
  const scenarios = rubric.scenarios as Record<string, boolean>[];
  const run = (rule: { if: Expr; then: string; else: string }) => scenarios.map((facts) => evalExpr(rule.if, facts) ? rule.then : rule.else);
  const key = run(target);
  // A hidden set on which the target always does the same thing proves nothing (Part 4.6).
  if (new Set(key).size < 2) return INVALID;
  if (run(learner).every((value, index) => value === key[index])) return grade('met');
  const used = exprConditions(learner.if); const needed = exprConditions(target.if);
  return grade('review', used.size !== needed.size || [...needed].some((item) => !used.has(item)) ? 'structure' : 'outcome');
}

type Tree = { o: string } | { q: string; yes: Tree; no: Tree };
function treeOk(value: unknown, questions: readonly string[], outcomes: readonly string[], asked: readonly string[] = []): value is Tree {
  if (!record(value)) return false;
  if (Object.keys(value).length === 1 && typeof value.o === 'string') return outcomes.includes(value.o);
  return Object.keys(value).length === 3 && typeof value.q === 'string' && questions.includes(value.q) && !asked.includes(value.q)
    && treeOk(value.yes, questions, outcomes, [...asked, value.q]) && treeOk(value.no, questions, outcomes, [...asked, value.q]);
}
function walkTree(tree: Tree, answers: Record<string, boolean>): string {
  return 'o' in tree ? tree.o : walkTree(answers[tree.q] ? tree.yes : tree.no, answers);
}
function treeQuestions(tree: Tree, out = new Set<string>()): Set<string> {
  if (!('o' in tree)) { out.add(tree.q); treeQuestions(tree.yes, out); treeQuestions(tree.no, out); }
  return out;
}
function builtFlowGrade(payload: Record<string, unknown>, response: unknown, rubric: unknown): V2Grade {
  if (!fields(payload, ['mode', 'questionIds', 'outcomeIds']) || !strings(payload.questionIds, 1, 3) || !strings(payload.outcomeIds, 2, 3)
    || !fields(response, ['tree'])) return INVALID;
  const questions = payload.questionIds as string[]; const outcomes = payload.outcomeIds as string[];
  if (!treeOk(response.tree, questions, outcomes)) return INVALID;
  if (rubric === undefined) return grade('valid');
  if (!fields(rubric, ['cases']) || !Array.isArray(rubric.cases) || rubric.cases.length < 5 || rubric.cases.length > 10
    || rubric.cases.some((item) => !fields(item, ['answers', 'outcome']) || !factsOk(item.answers, questions) || !outcomes.includes(item.outcome as string))) return INVALID;
  const cases = rubric.cases as Array<{ answers: Record<string, boolean>; outcome: string }>;
  if (new Set(cases.map((item) => item.outcome)).size < 2) return INVALID;
  const tree = response.tree as Tree;
  if (cases.every((item) => walkTree(tree, item.answers) === item.outcome)) return grade('met');
  // A chart that never asks a question the cases depend on is a structure (path) error.
  return grade('review', treeQuestions(tree).size < questions.length ? 'path' : 'outcome');
}

/* M8 schema diagrams (GAP-FIX-R2): four schemas, three slots each. */
/* M7 bar models (GAP-FIX-R3): the built structure, its consistency and its unknown. */
export type BarSlots = Record<string, string | null>;
const BAR_SLOT_NAMES: Readonly<Record<string, { required: readonly string[]; optional: readonly string[] }>> = {
  'part-whole': { required: ['part-a', 'part-b', 'whole'], optional: ['part-c'] },
  comparison: { required: ['smaller', 'larger', 'difference'], optional: ['total'] },
};
/**
 * The model's length relations, each sum(coefficient x slot) = 0. A part the
 * build left out drops its term; a comparison without its total bracket drops
 * the relations that name the total.
 */
const BAR_RELATIONS: Readonly<Record<string, ReadonlyArray<Readonly<Record<string, number>>>>> = {
  'part-whole': [{ whole: 1, 'part-a': -1, 'part-b': -1, 'part-c': -1 }],
  comparison: [{ larger: 1, smaller: -1, difference: -1 }, { total: 1, larger: -1, smaller: -1 }, { total: 1, smaller: -2, difference: -1 }, { total: 1, larger: -2, difference: 1 }],
};
function barQuantities(payload: unknown): { ids: string[]; values: number[] } | null {
  if (!fields(payload, ['quantityIds', 'values']) || !strings(payload.quantityIds, 2, 3) || !Array.isArray(payload.values) || payload.values.length !== payload.quantityIds.length
    || payload.values.some((value) => !whole(value) || value < 1 || value > 100_000) || payload.quantityIds.includes('unknown')
    || new Set(payload.quantityIds).size !== payload.quantityIds.length) return null;
  return { ids: payload.quantityIds as string[], values: payload.values as number[] };
}
/**
 * A complete build: the model's required slots (and any optional one the
 * learner added), each quantity placed exactly once and the unknown exactly
 * once. Only a comparison bar may carry no number (null).
 */
export function barBuild(model: unknown, slots: unknown, quantityIds: readonly string[]): boolean {
  if (typeof model !== 'string' || !Object.hasOwn(BAR_SLOT_NAMES, model) || !record(slots)) return false;
  const names = BAR_SLOT_NAMES[model]!;
  const keys = Object.keys(slots);
  if (names.required.some((name) => !keys.includes(name)) || keys.some((key) => !names.required.includes(key) && !names.optional.includes(key))) return false;
  for (const key of keys) {
    const value = slots[key];
    if (value === null) { if (model !== 'comparison' || !names.required.includes(key)) return false; continue; }
    if (typeof value !== 'string' || (value !== 'unknown' && !quantityIds.includes(value))) return false;
  }
  const placed = Object.values(slots);
  return placed.filter((value) => value === 'unknown').length === 1 && quantityIds.every((quantityId) => placed.filter((value) => value === quantityId).length === 1);
}
/**
 * The lengths a build implies, from the quantities it names: every slot the
 * relations can determine, each a positive whole number, with every relation
 * whose slots are all known holding. Null when the build contradicts itself
 * (a part longer than its whole, a smaller bar longer than the larger one).
 */
export function solveBarModel(model: string, slots: BarSlots, quantities: { ids: readonly string[]; values: readonly number[] }): Record<string, number> | null {
  const relations = BAR_RELATIONS[model];
  if (!relations) return null;
  const known: Record<string, number> = {};
  for (const [slot, value] of Object.entries(slots)) {
    const index = value === null || value === 'unknown' ? -1 : quantities.ids.indexOf(value);
    if (index >= 0) known[slot] = quantities.values[index]!;
  }
  const present = new Set(Object.keys(slots));
  const active = relations.filter((relation) => model !== 'comparison' || Object.keys(relation).every((slot) => present.has(slot)))
    .map((relation) => Object.fromEntries(Object.entries(relation).filter(([slot]) => present.has(slot))));
  for (let progress = true; progress;) {
    progress = false;
    for (const relation of active) {
      const open = Object.keys(relation).filter((slot) => known[slot] === undefined);
      const sum = Object.entries(relation).reduce((total, [slot, coefficient]) => total + (known[slot] === undefined ? 0 : coefficient * known[slot]!), 0);
      if (open.length === 0) { if (sum !== 0) return null; continue; }
      if (open.length !== 1) continue;
      const value = -sum / relation[open[0]!]!;
      if (!whole(value) || value < 1) return null;
      known[open[0]!] = value; progress = true;
    }
  }
  return known;
}
/** The unknown's value in a build, or null when the build cannot determine it consistently. */
export function barModelUnknown(model: string, slots: BarSlots, quantities: { ids: readonly string[]; values: readonly number[] }): number | null {
  const unknownSlot = Object.keys(slots).find((slot) => slots[slot] === 'unknown');
  const solved = unknownSlot ? solveBarModel(model, slots, quantities) : null;
  return solved && unknownSlot && solved[unknownSlot] !== undefined ? solved[unknownSlot]! : null;
}
/** The same model and the same slots; a part-whole's parts compare as a set (their order on the bar is free). */
function sameBarBuild(model: string, slots: BarSlots, keyModel: string, key: BarSlots): boolean {
  if (model !== keyModel) return false;
  if (model === 'part-whole') {
    const parts = (build: BarSlots) => ['part-a', 'part-b', 'part-c'].filter((slot) => Object.hasOwn(build, slot)).map((slot) => build[slot]).sort().join('|');
    return slots.whole === key.whole && parts(slots) === parts(key);
  }
  const keys = new Set([...Object.keys(slots), ...Object.keys(key)]);
  return [...keys].every((slot) => Object.hasOwn(slots, slot) && Object.hasOwn(key, slot) && slots[slot] === key[slot]);
}

const SCHEMAS: readonly string[] = ['change', 'group', 'compare', 'ratio'];
const SCHEMA_SLOT_NAMES: Readonly<Record<string, readonly string[]>> = {
  change: ['start', 'change', 'result'], group: ['part', 'other', 'total'], compare: ['larger', 'smaller', 'difference'], ratio: ['rate', 'count', 'total'],
};
function schemaQuantities(payload: unknown): { ids: string[]; values: number[] } | null {
  if (!fields(payload, ['quantityIds', 'values']) || !strings(payload.quantityIds, 2, 2) || !Array.isArray(payload.values) || payload.values.length !== 2
    || payload.values.some((value) => !whole(value) || value < 1 || value > 100_000) || payload.quantityIds.includes('unknown')) return null;
  return { ids: payload.quantityIds as string[], values: payload.values as number[] };
}
/** Exactly the schema's three slots; each story quantity placed once and the unknown once. */
function schemaSlots(schema: unknown, slots: unknown, quantityIds: readonly string[]): boolean {
  if (typeof schema !== 'string' || !SCHEMAS.includes(schema) || !record(slots)) return false;
  const names = SCHEMA_SLOT_NAMES[schema]!;
  if (Object.keys(slots).length !== 3 || names.some((name) => typeof slots[name] !== 'string')) return false;
  const placed = names.map((name) => slots[name] as string);
  return placed.filter((value) => value === 'unknown').length === 1 && quantityIds.every((quantityId) => placed.filter((value) => value === quantityId).length === 1);
}

/* M5 place value (GAP-FIX-R2): columns, trades and borrows. */
interface PlaceColumns { hundreds: number; tens: number; ones: number; subtrahend: number }
const COMPOSE_TRADES: readonly string[] = ['ten', 'hundred'];
const BORROW_TRADES: readonly string[] = ['borrow-ten', 'borrow-hundred'];
function placeColumns(payload: unknown): PlaceColumns | null {
  if (!fields(payload, ['mode', 'hundreds', 'tens', 'ones', 'subtrahend']) || (payload.mode !== 'compose' && payload.mode !== 'subtract')
    || !onGrid(payload.hundreds, 0, 9, 1) || !onGrid(payload.tens, 0, 29, 1) || !onGrid(payload.ones, 0, 29, 1) || !onGrid(payload.subtrahend, 0, 998, 1)) return null;
  const value = payload.hundreds * 100 + payload.tens * 10 + payload.ones;
  if (value < 10 || value > 999 || (payload.mode === 'compose') !== (payload.subtrahend === 0) || payload.subtrahend >= value) return null;
  return { hundreds: payload.hundreds, tens: payload.tens, ones: payload.ones, subtrahend: payload.subtrahend };
}
function replayPlaceTrades(start: PlaceColumns, trades: unknown): { hundreds: number; tens: number; ones: number } | null {
  const allowed = start.subtrahend === 0 ? COMPOSE_TRADES : BORROW_TRADES;
  if (!Array.isArray(trades) || trades.length > 20) return null;
  let { hundreds, tens, ones } = start;
  for (const trade of trades) {
    if (typeof trade !== 'string' || !allowed.includes(trade)) return null;
    if (trade === 'ten') { if (ones < 10) return null; ones -= 10; tens += 1; }
    else if (trade === 'hundred') { if (tens < 10 || hundreds >= 9) return null; tens -= 10; hundreds += 1; }
    else if (trade === 'borrow-ten') { if (tens < 1 || ones > 9) return null; tens -= 1; ones += 10; }
    else { if (hundreds < 1 || tens > 9) return null; hundreds -= 1; tens += 10; }
  }
  return { hundreds, tens, ones };
}
function composeTrades(start: PlaceColumns): number {
  const tenTrades = Math.floor(start.ones / 10);
  return tenTrades + Math.floor((start.tens + tenTrades) / 10);
}
function borrowCount(start: PlaceColumns): number {
  let { hundreds, tens, ones } = start;
  const s = { hundreds: Math.floor(start.subtrahend / 100), tens: Math.floor(start.subtrahend / 10) % 10, ones: start.subtrahend % 10 };
  let borrows = 0;
  if (ones < s.ones) { if (tens === 0) { hundreds -= 1; tens += 10; borrows += 1; } tens -= 1; ones += 10; borrows += 1; }
  if (tens < s.tens) { hundreds -= 1; tens += 10; borrows += 1; }
  return hundreds < s.hundreds ? -1 : borrows;
}

function scoreV2Extended(kind: V2VisualKind, payload: unknown, response: unknown, rubric: unknown): V2VisualVerdict {
  return scoreV2ExtendedDetailed(kind, payload, response, rubric).verdict;
}

function scoreV2ExtendedDetailed(kind: V2VisualKind, payload: unknown, response: unknown, rubric: unknown): V2Grade {
  switch (kind) {
    case 'math.place-value.v2': {
      // M5 (GAP-FIX-R2): three places. The trade sequence is replayed from the start columns, then the written digits.
      const start = placeColumns(payload);
      if (!start || !fields(response, ['trades', 'hundreds', 'tens', 'ones']) || !numberText(response.hundreds) || !numberText(response.tens)
        || !numberText(response.ones)) return INVALID;
      const final = replayPlaceTrades(start, response.trades);
      if (!final) return INVALID;
      const expectedTrades = start.subtrahend === 0 ? composeTrades(start) : borrowCount(start);
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['trades']) || !whole(rubric.trades) || rubric.trades !== expectedTrades || expectedTrades < 1) return INVALID;
      const s = { hundreds: Math.floor(start.subtrahend / 100), tens: Math.floor(start.subtrahend / 10) % 10, ones: start.subtrahend % 10 };
      const structured = start.subtrahend === 0 ? final.ones < 10 && final.tens < 10
        : (response.trades as unknown[]).length === expectedTrades && final.ones >= s.ones && final.tens >= s.tens && final.hundreds >= s.hundreds;
      if (!structured) return grade('review', 'structure');
      const value = start.subtrahend === 0 ? final : { hundreds: final.hundreds - s.hundreds, tens: final.tens - s.tens, ones: final.ones - s.ones };
      return Number(response.hundreds) === value.hundreds && Number(response.tens) === value.tens && Number(response.ones) === value.ones
        ? grade('met') : grade('review', 'value');
    }
    case 'math.ratio-table.v2': {
      // M14: the chosen pair and the missing value.
      if (!fields(payload, ['itemsPerPack', 'pricePerPack', 'minimumPacks', 'maximumPacks']) || !whole(payload.itemsPerPack) || !whole(payload.pricePerPack)
        || !whole(payload.minimumPacks) || !whole(payload.maximumPacks) || payload.maximumPacks <= payload.minimumPacks
        || !fields(response, ['packs', 'price']) || !onGrid(response.packs, payload.minimumPacks, payload.maximumPacks, 1) || !numberText(response.price)) return INVALID;
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['target_packs']) || !onGrid(rubric.target_packs, payload.minimumPacks, payload.maximumPacks, 1)) return INVALID;
      if (response.packs !== rubric.target_packs) return grade('review', 'structure');
      return sameAnswer(response.price, String(rubric.target_packs * payload.pricePerPack)) ? grade('met') : grade('review', 'value');
    }
    case 'visual.percent-grid.v2': {
      // M15: the shaded count (snapped), the marker percent and the amount.
      if (!fields(payload, ['baseUnits', 'step']) || !whole(payload.baseUnits) || payload.baseUnits <= 0 || !whole(payload.step) || payload.step <= 0 || 100 % payload.step !== 0
        || !fields(response, ['percent', 'amount']) || !onGrid(response.percent, 0, 100, payload.step) || !numberText(response.amount)) return INVALID;
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['target_percent']) || !onGrid(rubric.target_percent, 0, 100, payload.step)) return INVALID;
      if (response.percent !== rubric.target_percent) return grade('review', 'structure');
      return sameAnswer(response.amount, String(payload.baseUnits * response.percent / 100)) ? grade('met') : grade('review', 'value');
    }
    case 'visual.growth-comparison.v2': {
      // M19: a committed prediction, graded within the private tolerance (Part 4.2).
      if (!fields(payload, ['principalMinor', 'minimumRateBps', 'maximumRateBps', 'rateStepBps', 'minimumYears', 'maximumYears', 'yearStep', 'predictionStepMinor', 'predictionMaximumMinor'])) return INVALID;
      const p = payload as Record<string, number>;
      if (!fields(response, ['rateBps', 'years', 'predictionMinor']) || !onGrid(response.rateBps, p.minimumRateBps!, p.maximumRateBps!, p.rateStepBps!)
        || !onGrid(response.years, p.minimumYears!, p.maximumYears!, p.yearStep!)
        || !onGrid(response.predictionMinor, p.principalMinor!, p.predictionMaximumMinor!, p.predictionStepMinor!)) return INVALID;
      const actual = compoundMinor(p.principalMinor!, response.rateBps, response.years);
      if (actual === null) return INVALID;
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['tolerance_minor']) || !whole(rubric.tolerance_minor) || rubric.tolerance_minor < 0 || rubric.tolerance_minor > p.predictionMaximumMinor!) return INVALID;
      return Math.abs(response.predictionMinor - actual) <= rubric.tolerance_minor ? grade('met') : grade('review', 'tolerance');
    }
    case 'visual.tax-bracket.v2': {
      // M20 (Appendix P: "tax owed; marginal and average rates"; GAP-FIX-R5): all three at the asked income.
      if (!fields(payload, ['minimumIncomeMinor', 'maximumIncomeMinor', 'incomeStepMinor', 'brackets']) || !whole(payload.minimumIncomeMinor) || !whole(payload.maximumIncomeMinor)
        || !whole(payload.incomeStepMinor) || payload.incomeStepMinor <= 0
        || !fields(response, ['incomeMinor', 'taxMinor', 'marginalBps', 'averageBps']) || !onGrid(response.incomeMinor, payload.minimumIncomeMinor, payload.maximumIncomeMinor, payload.incomeStepMinor)
        || !numberText(response.taxMinor) || !whole(response.marginalBps) || response.marginalBps < 0 || response.marginalBps > 10_000
        || !whole(response.averageBps) || response.averageBps < 0 || response.averageBps > 10_000) return INVALID;
      const owed = taxOwed(response.incomeMinor, payload.brackets);
      if (!owed) return INVALID;
      if (rubric === undefined) return grade('valid');
      // The average rate is typed as a percent, so the key accepts it within half a point by default (at most one point).
      if (!keysIn(rubric, ['income_minor'], ['average_tolerance_bps']) || !onGrid(rubric.income_minor, payload.minimumIncomeMinor, payload.maximumIncomeMinor, payload.incomeStepMinor)
        || (rubric.average_tolerance_bps !== undefined && !onGrid(rubric.average_tolerance_bps, 0, 100, 1))) return INVALID;
      if (response.incomeMinor !== rubric.income_minor) return grade('review', 'structure');
      const averageTolerance = (rubric.average_tolerance_bps as number | undefined) ?? 50;
      const right = [sameAnswer(response.taxMinor, String(owed.tax)), response.marginalBps === owed.marginal, Math.abs(response.averageBps - owed.average) <= averageTolerance];
      const count = right.filter(Boolean).length;
      return count === 3 ? grade('met') : grade('review', count > 0 ? 'partial' : 'value');
    }
    case 'logic.savings-rule.v2': {
      // L2 (Part 4.6): the learner's rule is compiled and run on held-out cases, never matched as text.
      if (!fields(payload, ['goal']) || !whole(payload.goal) || payload.goal < 2 || payload.goal > 100
        || !fields(response, ['comparator', 'threshold', 'link']) || typeof response.comparator !== 'string' || !COMPARATORS.includes(response.comparator)
        || !onGrid(response.threshold, 0, payload.goal * 2, 1) || typeof response.link !== 'string' || !LINKS.includes(response.link)) return INVALID;
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['comparator', 'threshold', 'link', 'held_out']) || typeof rubric.comparator !== 'string' || !COMPARATORS.includes(rubric.comparator)
        || !onGrid(rubric.threshold, 0, payload.goal * 2, 1) || typeof rubric.link !== 'string' || !LINKS.includes(rubric.link)
        || !Array.isArray(rubric.held_out) || rubric.held_out.length < 2 || rubric.held_out.length > 8) return INVALID;
      const goal = payload.goal;
      const cases = rubric.held_out;
      if (cases.some((item) => !fields(item, ['saved', 'goal_day']) || !onGrid(item.saved, 0, goal * 2, 1) || typeof item.goal_day !== 'boolean')) return INVALID;
      const key = cases.map((item) => ruleOutcome(item.saved as number, item.goal_day as boolean, rubric.comparator as RuleComparator, rubric.threshold as number, rubric.link as RuleLink));
      // A held-out set where the key rule is always true or always false proves nothing.
      if (!key.includes(true) || !key.includes(false)) return INVALID;
      const learner = cases.map((item) => ruleOutcome(item.saved as number, item.goal_day as boolean, response.comparator as RuleComparator, response.threshold as number, response.link as RuleLink));
      if (learner.every((value, index) => value === key[index])) return grade('met');
      return grade('review', response.link !== rubric.link ? 'structure' : 'value');
    }
    case 'visual.goal-bullet.v2': {
      if (!fields(payload, ['minimum', 'maximum', 'step']) || !whole(payload.minimum) || !whole(payload.maximum) || !whole(payload.step) || payload.step <= 0
        || !fields(response, ['value']) || !onGrid(response.value, payload.minimum, payload.maximum, payload.step)) return INVALID;
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['minimum_value']) || !onGrid(rubric.minimum_value, payload.minimum, payload.maximum, payload.step) || rubric.minimum_value === payload.minimum) return INVALID;
      return response.value >= rubric.minimum_value ? grade('met') : grade('review', 'value');
    }
    case 'money.running-ledger.v2': {
      if (!fields(payload, ['initial', 'sale', 'cost', 'maxEntries']) || !whole(payload.initial) || !whole(payload.sale) || !whole(payload.cost) || !whole(payload.maxEntries)
        || !fields(response, ['entries', 'balance']) || !Array.isArray(response.entries) || response.entries.length > payload.maxEntries
        || response.entries.some((entry) => entry !== 'sale' && entry !== 'cost') || !numberText(response.balance)) return INVALID;
      const sale = payload.sale; const cost = payload.cost;
      // Conservation: the balance is always the opening amount plus every sale minus every cost.
      const computed = (response.entries as string[]).reduce((sum, entry) => sum + (entry === 'sale' ? sale : -cost), payload.initial);
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['target_balance']) || !whole(rubric.target_balance) || rubric.target_balance === payload.initial) return INVALID;
      if (computed !== rubric.target_balance) return grade('review', 'structure');
      return sameAnswer(response.balance, String(computed)) ? grade('met') : grade('review', 'value');
    }
    case 'logic.rule-checker.v2': {
      if (!fields(payload, ['cardIds']) || !strings(payload.cardIds, 3, 6) || !fields(response, ['flipped']) || !strings(response.flipped, 1, 6)
        || response.flipped.some((card) => !(payload.cardIds as string[]).includes(card))) return INVALID;
      if (rubric === undefined) return grade('valid');
      const cards = payload.cardIds as string[];
      if (!fields(rubric, record(rubric) && rubric.roles !== undefined ? ['must_flip_ids', 'roles'] : ['must_flip_ids']) || !strings(rubric.must_flip_ids, 1, cards.length - 1) || rubric.must_flip_ids.some((card) => !cards.includes(card))) return INVALID;
      const need = new Set(rubric.must_flip_ids);
      const roles = ruleCardRoles(rubric, cards, need);
      if (roles === 'invalid') return INVALID;
      const flipped = new Set(response.flipped as string[]);
      const missing = [...need].some((card) => !flipped.has(card));
      const extra = [...flipped].some((card) => !need.has(card));
      if (!missing && !extra) return grade('met');
      const selection = roles ? selectionDiagnostic([...flipped].map((card) => roles[card]!), cards.length === flipped.size) : null;
      return grade('review', selection ?? (missing && extra ? 'partial' : missing ? 'miss' : 'false_alarm'));
    }
    case 'logic.euler.v2': return eulerGrade(payload, response, rubric);
    case 'logic.flowchart.v2':
    case 'money.spend-decision.v2': {
      if (record(payload) && payload.mode === 'build') return builtFlowGrade(payload, response, rubric);
      if (!fields(payload, ['start', 'nodes', 'scenarioIds']) || !strings(payload.scenarioIds, 1, 3) || !fields(response, ['paths']) || !record(response.paths)) return INVALID;
      const scenarios = payload.scenarioIds as string[];
      const paths = response.paths;
      if (Object.keys(paths).length !== scenarios.length || scenarios.some((scenario) => !flowPath(payload, paths[scenario]))) return INVALID;
      if (rubric === undefined) return grade('valid');
      if (!fields(rubric, ['paths']) || !record(rubric.paths) || Object.keys(rubric.paths).length !== scenarios.length) return INVALID;
      const keys = rubric.paths;
      if (scenarios.some((scenario) => !flowPath(payload, keys[scenario]))) return INVALID;
      let pathWrong = false; let outcomeWrong = false;
      for (const scenario of scenarios) {
        const given = paths[scenario] as string[];
        const key = keys[scenario] as string[];
        if (given.at(-1) !== key.at(-1)) outcomeWrong = true;
        else if (given.join('>') !== key.join('>')) pathWrong = true;
      }
      return !pathWrong && !outcomeWrong ? grade('met') : grade('review', outcomeWrong ? 'outcome' : 'path');
    }
    case 'logic.sort-by-rule.v2':
    case 'money.needs-wants.v2': return sortGrade(payload, response, rubric);
    case 'logic.scam-spotter.v2':
    case 'money.scam-check.v2': return detectionGrade(payload, response, rubric);
    case 'money.coin-tray.v2': {
      if (!record(payload)) return INVALID;
      const total = money(payload, response);
      if (total === null) return INVALID;
      if (rubric === undefined) return grade('valid');
      const denominations = payload.denominations as Array<{ value: number; available: number }>;
      const most = denominations.reduce((sum, item) => sum + item.value * item.available, 0);
      if (!fields(rubric, ['target_minor', 'fewest']) || !whole(rubric.target_minor) || rubric.target_minor <= 0 || rubric.target_minor > most
        || typeof rubric.fewest !== 'boolean' || rubric.target_minor > 100_000) return INVALID;
      const fewest = fewestPieces(rubric.target_minor, denominations);
      if (fewest === null) return INVALID;
      if (total !== rubric.target_minor) return grade('review', 'value');
      const pieces = Object.values((response as { counts: Record<string, number> }).counts).reduce((sum, count) => sum + count, 0);
      return !rubric.fewest || pieces === fewest ? grade('met') : grade('review', 'partial');
    }
    case 'money.making-change.v2': {
      if (!fields(payload, ['denominations', 'price', 'paid']) || !whole(payload.price) || !whole(payload.paid) || payload.paid <= payload.price) return INVALID;
      // $2 (GAP-FIX-R2): the coins returned and the counting-up sequence said while adding them, in order.
      if (!fields(response, ['counts', 'sequence'])) return INVALID;
      const total = money(payload, { counts: response.counts });
      if (total === null) return INVALID;
      const counting = countUp(payload.denominations as Array<{ value: number }>, response.counts as Record<string, number>, response.sequence, payload.price, payload.paid);
      if (counting === null) return INVALID;
      if (rubric === undefined) return grade('valid');
      // Conservation: the change owed is exactly what was paid minus the price.
      if (!fields(rubric, ['change_minor']) || rubric.change_minor !== payload.paid - payload.price) return INVALID;
      if (total !== rubric.change_minor) return grade('review', 'value');
      // Laski & Siegler: count UP from the price to the amount paid; counting the change from zero is a diagnosed review.
      return counting === 'from_price' ? grade('met') : grade('review', counting === 'from_zero' ? 'count_from_zero' : 'value');
    }
    case 'story.branch.v2':
    case 'story.dialogue-choice.v2': return choiceGrade(payload, response, rubric, 3);
    case 'story.would-you-rather.v2': return choiceGrade(payload, response, rubric, 2);
    // B.7 part 1: a question read off a teaching chart; the acceptable option ids are private.
    case 'visual.chart.v2': return choiceGrade(payload, response, rubric, 3, 4);
    case 'money.unit-price.v2': return unitPriceGrade(payload, response, rubric);
    case 'logic.rule-builder.v2': return ruleBuilderGrade(payload, response, rubric);
    default: return INVALID;
  }
}
